from math import floor, log2
from typing import List


def window_weights(arc: List[float], r: int) -> List[float]:
    """All cyclic window weights: sums of r consecutive pieces."""
    n = len(arc)
    return [sum(arc[(i + j) % n] for j in range(r)) for i in range(n)]


def mu(arc: List[float], r: int) -> float:
    """Cake-balancing ratio mu_r = max window / min window."""
    w = window_weights(arc, r)
    return max(w) / min(w)


def verify_aggregation(arc: List[float]) -> None:
    """Check mu_r <= mu_1 for all r (aggregation never increases imbalance)."""
    mu1 = mu(arc, 1)
    for r in range(1, len(arc) + 1):
        m = mu(arc, r)
        assert m >= 1 - 1e-12, "lower bound one violated"
        assert m <= mu1 + 1e-12, "aggregation principle violated"
        print(f"  r={r}: mu_r = {m:.4f}  (<= mu_1 = {mu1:.4f})")


if __name__ == "__main__":
    verify_aggregation([0.30, 0.10, 0.25, 0.15, 0.20])

