function THREE_GAP_LENGTHS(alpha, n):
    pts <- sorted list of (m * alpha mod 1) for m = 1..n
    gaps <- []
    for i from 0 to n-2:
        append pts[i+1] - pts[i] to gaps
    append (1 - pts[n-1] + pts[0]) to gaps    # wrap-around gap
    distinct <- number of distinct values in gaps (rounded)
    return (gaps, distinct)
